INSERT INTO `clothingregulation` (`id`, `name`, `created_at`, `updated_at`) VALUES
(1, 'Los colaboradores deberán mantener estándares de una buena higiene en todo momento.', '2023-09-21 12:22:36', '2023-09-21 12:28:34'),
(2, 'La vestimenta y los zapatos deben estar limpios.', '2023-09-21 12:22:47', '2023-09-21 12:22:47'),
(3, 'El cabello debe estar limpio y peinado de forma profesional.', '2023-09-21 12:22:59', '2023-09-21 12:22:59'),
(4, 'Las damas deben bien arregladas y maquilladas.', '2023-09-21 12:23:10', '2023-09-21 12:23:10'),
(5, 'El uniforme debe estar limpio y en excelente condición en todo momento. ', '2023-09-21 12:23:47', '2023-09-21 12:23:47'),
(6, 'Camisa negra, con los logos (En caso de no poseer, camisa del uniforme, una camisa manga larga o manga corta negra).', '2023-09-21 12:24:00', '2023-09-21 12:24:00'),
(7, 'Pantalón de mezclilla Negro (No roto, con enmendaduras, deslavado o en malas condiciones).', '2023-09-21 12:24:10', '2023-09-21 12:24:10'),
(8, 'No está permitido el uso de zapatos deportivos en ninguna de las áreas de la empresa.', '2023-09-21 12:24:25', '2023-09-21 12:24:25'),
(9, 'Para todas las vestimentas el color de los zapatos deben de ser negros de vestir. ', '2023-09-25 12:02:40', '2023-09-25 12:02:40');
