(18054, 6, 3, '{\"status_data\":\"4\",\"id\":\"94\",\"observation\":\"SE ESCRIBIO AL WHATSAPP\\r\\n\\r\\nESE DIA SE LE ENVIO LA INFORMACION COMPLETA AL WHATSAPP PERO NO RESPONDIO \\r\\n\\r\\nLE VOLVI A ESCRIBIR A VER QUE PASO \"}', 'post', '/assigned_clients/edit_assigned_clients/117', '2023-08-09 14:53:20', '2023-08-09 14:53:20'),
(18055, 6, 3, '{\"status_data\":\"4\",\"id\":\"149\",\"observation\":\"CONVERSAMOS POR LLAMADA DE CADA TORRE, ME PIDIO QUE LE ENVIARA LA LISTA DE LAS OFICINAS DISPONIBLES. EN ESPERA PARA PODER VERIFICAR SI EVALUO \\r\\n\\r\\nEL SE\\u00d1OR DESISTIO PORQUE LE PARECE EL M2 MUY CARO Y PREFIERE BUSCAR DE CONTADO APARTE YA ESTABA VIENDO OTRAS OPCIONES \"}', 'post', '/assigned_clients/edit_assigned_clients/205', '2023-08-09 14:55:24', '2023-08-09 14:55:24'),
(18056, 66, 3, '{\"first_contact_at\":\"2023-08-09 14:55:55\",\"status_data\":\"8\",\"id\":\"1937\",\"observation\":\"LE PARECE DEMASIADO COSTOSO\"}', 'post', '/assigned_clients/edit_assigned_clients/1981', '2023-08-09 14:56:19', '2023-08-09 14:56:19'),
(18057, 6, 3, '{\"status_data\":\"4\",\"id\":\"116\",\"observation\":\"YA HABIA SIDO ATENDIDO POR YESENIA DE OTRA INMOBILIARIA, SIN EMBARGO LE INDIQUE QUE LE PODEMOS DAR 16 MESES DE FINANCIAMIENTO. INTERESADO EN 3 OFICINAS  CON FINANCIAMIENTO\\r\\n\\r\\nNO RESPONDIO MAS, NO SE SABE QUE PASO CON EL CLIENTE \"}', 'post', '/assigned_clients/edit_assigned_clients/195', '2023-08-09 14:57:03', '2023-08-09 14:57:03'),
(18058, 6, 3, '{\"status_data\":\"21\",\"id\":\"148\",\"observation\":\"QUIERE SABER A QUE ALTURA DE LA COTA MIL SE ENCUENTRA EL CONJUNTO. YA SE MANTENIA EN CONTACTO \\r\\n\\r\\nYA NO SE ENCUENTRA INTERESADA, YA SE HABIA ENVIADO TODA LA INFORMACION DE QUARZO BOTANIKO Y LA VISTA\"}', 'post', '/assigned_clients/edit_assigned_clients/196', '2023-08-09 14:58:04', '2023-08-09 14:58:04'),
(18059, 66, 3, '{\"first_contact_at\":\"2023-08-09 15:04:39\",\"status_data\":\"18\",\"id\":\"1936\",\"observation\":\"SE LE DIO INF Y SE PASO VIA WHATSAPP SE AGENDO PARA OPEN HOUSE DE ESTE SABADO - PERO LE PARECE EXTREMADAMENTE CARO\"}', 'post', '/assigned_clients/edit_assigned_clients/1980', '2023-08-09 15:05:42', '2023-08-09 15:05:42'),
(18060, 6, 3, '{\"status_data\":\"4\",\"id\":\"266\",\"observation\":\"CLIENTE NO RESPONDE LLAMADA NI MENSAJES AL WHATSAPP YA SE LE HAN ENVIADO OPCIONES DESDE ENERO - AUN EN ESPERA DE RESPUESTA EFECTIVA \\r\\n\\r\\nESCRIBI HOY OTRA VEZ, INDICA QUE RETOMARA LA BUSQUEDA PARA FINALES DE A\\u00d1O, POR AHORA NO VAN A COMPRAR \"}', 'post', '/assigned_clients/edit_assigned_clients/221', '2023-08-09 15:07:06', '2023-08-09 15:07:06'),
(18061, 6, 3, '{\"status_data\":\"4\",\"id\":\"189\",\"observation\":\"NO RESPONDE LLAMADA, LE ESCRIBI AL WHATSAPP - RESPONDIO EL DIA DE HOY LE ENVIE INFORMACION DETALLADA \\r\\n\\r\\nEL CLIENTE INDICO EN ESE MOMENTO QUE EL M2 ESTA MUY CARO Y QUIERE 8 - 10 A\\u00d1OS DE FINANCIAMIENTO NO UN PLAZO TAN CORTO. \"}', 'post', '/assigned_clients/edit_assigned_clients/216', '2023-08-09 15:10:13', '2023-08-09 15:10:13'),
