(19578, 6, 3, '{\"status_data\":\"4\",\"id\":\"34\",\"observation\":\"SE ESCRIBIO VIA WHATSAPP AL CLIENTES, EN ESPERA DE RESPUESTA \\r\\n\\r\\nSE HABIA ENVIADO LA INFORMACION COMPLETA DE LA VISTA PERO NO RESPONDIO MAS PREGUNTO POR JABILLOS TAMBIEN ESE ENVIO INFORMACION PERO DEJO DE RESPONDER \\r\\n\\r\\nULTIMO INTENTO PARA DESCARTAR CLIENTE\\r\\n\\r\\nIMPOSIBLE CONTACTO CON EL CLIENTE \"}', 'post', '/assigned_clients/edit_assigned_clients/46', '2023-08-22 12:57:39', '2023-08-22 12:57:39'),
(19579, 6, 3, '{\"status_data\":\"4\",\"id\":\"34\",\"observation\":\"SE ESCRIBIO VIA WHATSAPP AL CLIENTES, EN ESPERA DE RESPUESTA \\r\\n\\r\\nSE HABIA ENVIADO LA INFORMACION COMPLETA DE LA VISTA PERO NO RESPONDIO MAS PREGUNTO POR JABILLOS TAMBIEN ESE ENVIO INFORMACION PERO DEJO DE RESPONDER  ULTIMO INTENTO PARA DESCARTAR CLIENTE IMPOSIBLE CONTACTAR AL CLIENTE\"}', 'post', '/assigned_clients/edit_assigned_clients/46', '2023-08-22 13:04:51', '2023-08-22 13:04:51'),
(19580, 6, 3, '{\"status_data\":\"3\",\"id\":\"41\",\"observation\":\"SE CONVERSO DE LAS OFICINAS DISPONIBLES EN JALISCO PERO NO SE NOTA MUY CONVENCIDA, SOLICITO SI TENIAMOS OFICINA EN SANTA PAULA DE 42M2 Y PASARLE LAS OPCIONES VIA WHATSAPP\\r\\n\\r\\nVIO JALISCO VIO OFICINAS EN EL CCCT PERO FUE IMPOSIBLE NEGOCIAR. YA QUE QUERIAN ALGO MUY GRANDE Y DE LUJO Y REGATEANDO MUCHO EL PRECIO. \"}', 'post', '/assigned_clients/edit_assigned_clients/68', '2023-08-22 13:07:45', '2023-08-22 13:07:45'),
(19581, 6, 3, '{\"status_data\":\"4\",\"id\":\"51\",\"observation\":\"SALE COMO SUSCRIPTOR SIN PODER LOCALIZAR, LE ESCRIBI AL WHATSAPP \\r\\n\\r\\nLLAME VARIAS VECES PERO ES IMPOSIBLE EL CONTACTO POR WHATSAPP Y POR LLAMADA \"}', 'post', '/assigned_clients/edit_assigned_clients/80', '2023-08-22 13:11:58', '2023-08-22 13:11:58'),
(19582, 6, 3, '{\"status_data\":\"4\",\"id\":\"39\",\"observation\":\"LA LLAMADA INDICA QUE NO PUEDE SER LOCALIZADO - ESCRIBI AL WHATSAPP\\r\\n\\r\\nSE HABIA ENVIADO ESE MISMO DIA LA INFORMACION COMPLETA PERO SOLO DIJO \\\"GRACIAS\\\" \\r\\n\\r\\nLE VOLVI A ESCRIBIRINDICA QUE ESTA EN EL FINIQUITO DE UN NEGOCIO PARA OPTAR POR LA COMPRA, AUN INTERESADO EN CONTACTO \"}', 'post', '/assigned_clients/edit_assigned_clients/96', '2023-08-22 13:13:10', '2023-08-22 13:13:10'),
